-- QA-F4-02 (medio) y QA-F4-01 (bajo), docs/qa/QA-9e912e5.md:
-- la comuna de una dirección no se validaba contra sus coordenadas, y el
-- "límite de Chile" era una caja que aceptaba Mendoza o Bolivia.
--
-- Solución: límites comunales simplificados + validación en el servidor.
-- Un punto es válido si está a 2,5 km o menos del polígono de la comuna
-- elegida. Como los polígonos son chilenos, eso también exige estar en Chile
-- (con la misma tolerancia en la frontera).
--
-- FUENTE DE LOS DATOS (no se inventó ninguna coordenada):
--   geoBoundaries, gbOpen CHL ADM3 ("Communes"), versión 9469f09:
--   https://github.com/wmgeolab/geoBoundaries/raw/9469f09/releaseData/gbOpen/CHL/ADM3/geoBoundaries-CHL-ADM3_simplified.geojson
--   SHA-256 del archivo: f6852723bc6d44d4813086fe9df750e7228e1925a72284e3d2b65ed44e2aa99a
--   Origen: Biblioteca del Congreso Nacional de Chile (BCN) y OCHA ROLAC
--   (2020), vía data.humdata.org. Licencia: Creative Commons Attribution 3.0
--   IGO (CC BY 3.0 IGO). Atribución: "Límites comunales © BCN / OCHA ROLAC,
--   distribuidos por geoBoundaries (Runfola et al., 2020), CC BY 3.0 IGO".
--
-- PROCESAMIENTO (PostGIS, reproducible):
--   area = ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_SnapToGrid(
--            ST_SimplifyPreserveTopology(ST_Buffer(geom, 0.01), 0.02), 0.001)), 3))
--   centro = ST_PointOnSurface(geom original), redondeado a 4 decimales
--     (siempre dentro de la comuna; la UI lo usa para centrar el mapa).
--   Error medido contra los vértices de la fuente: máximo 2,09 km (fiordos
--   australes) y p99 0,57 km. De ahí el margen de 2,5 km.
--   Consecuencia: en zonas urbanas densas, un punto a menos de 2,5 km del
--   límite se acepta también para la comuna vecina. Se rechaza lo incoherente
--   (otra región, otro país), y la UI propone la comuna correcta.
--
-- CORRECCIONES DE LA FUENTE (345 polígonos para 346 comunas):
--   * 'Calera' = La Calera, y 'Paihuano' = Paiguano (grafía del catálogo).
--   * Hay dos polígonos 'Tocopilla'. El que está al norte de 21° S es Pozo
--     Almonte: contiene el punto de Pozo Almonte de Wikidata (Q23660626, CC0,
--     -20,7702 / -69,5045), y el otro contiene el de Tocopilla (Q23660225).
--   * Control cruzado con Wikidata (CC0): de 340 comunas con coordenada, en 338
--     el punto del mismo nombre cae dentro de su polígono o a 5 km o menos. En
--     Vilcún (29 km) y Laguna Blanca (19 km), el punto aproximado de Wikidata
--     cae en una comuna vecina; manda el polígono de BCN. Las otras 5 comunas
--     no tienen coordenada en Wikidata.
--   * Antártica no tiene polígono en la fuente. Se acepta el Territorio
--     Chileno Antártico del Decreto 1747 de 1940 (entre los meridianos 53° y
--     90° O), al sur de 60° S (zona del Tratado Antártico).

-- La caja de lng se amplía hasta 53° O por el Territorio Antártico. La
-- validación real la hacen los polígonos.
alter table public.addresses drop constraint addresses_lng_check;
alter table public.addresses add constraint addresses_lng_check
  check (lng between -110 and -53);

create table public.commune_boundaries (
  commune_id integer primary key references public.communes (id),
  center_lat double precision not null check (center_lat between -90 and -17),
  center_lng double precision not null check (center_lng between -110 and -53),
  area extensions.geography(MultiPolygon, 4326) not null
);

create index commune_boundaries_area_gix
  on public.commune_boundaries using gist (area);

insert into public.commune_boundaries (commune_id, center_lat, center_lng, area)
select c.id, v.lat, v.lng, extensions.st_geogfromtext('SRID=4326;' || v.wkt)
