join public.communes c on c.region_id = v.region_id and c.name = v.name;

do $$
begin
  if (select count(*) from public.commune_boundaries) <> 345 then
    raise exception 'Se esperaban 345 límites comunales (todas menos Antártica)';
  end if;
end;
$$;

-- Dato de referencia: lo leen los usuarios autenticados (centrar el mapa,
-- proponer la comuna). Solo se modifica por migración.
alter table public.commune_boundaries enable row level security;
alter table public.commune_boundaries force row level security;

create policy commune_boundaries_read on public.commune_boundaries
for select to authenticated using (true);

revoke all on public.commune_boundaries from public, anon, authenticated;
grant select on public.commune_boundaries to authenticated;

-- Margen de la validación (ver la cabecera): 2,5 km.
create function private.commune_tolerance_m()
returns double precision
language sql
immutable
set search_path = ''
as $$ select 2500::double precision $$;
revoke execute on function private.commune_tolerance_m() from public, anon, authenticated;

-- ¿El punto está en Chile? (cerca de alguna comuna o en el Territorio Antártico)
create function private.point_in_chile(p_lat double precision, p_lng double precision)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (p_lat <= -60 and p_lng between -90 and -53)
      or exists (
        select 1 from public.commune_boundaries b
        where extensions.st_dwithin(
          b.area,
          extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography,
          private.commune_tolerance_m()));
$$;
revoke execute on function private.point_in_chile(double precision, double precision)
  from public, anon, authenticated;

-- ¿El punto corresponde a la comuna?
create function private.point_in_commune(
  p_commune integer, p_lat double precision, p_lng double precision)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when b.commune_id is null then
      -- Solo Antártica no tiene polígono (ver la cabecera).
      c.name = 'Antártica' and c.region_id = 12
      and p_lat <= -60 and p_lng between -90 and -53
    else extensions.st_dwithin(
      b.area,
      extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography,
      private.commune_tolerance_m())
  end
  from public.communes c
  left join public.commune_boundaries b on b.commune_id = c.id
  where c.id = p_commune;
$$;
revoke execute on function private.point_in_commune(integer, double precision, double precision)
  from public, anon, authenticated;

-- Guardián de direcciones: suma la validación del punto contra la comuna.
create or replace function private.guard_address()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.owner_id is distinct from old.owner_id then
    raise exception 'No se puede cambiar el dueño de una dirección' using errcode = '42501';
  end if;

  new.label := trim(new.label);
  new.street_text := trim(new.street_text);
  new.details := nullif(trim(new.details), '');

  -- QA-F4-01/02: el punto debe estar en Chile y en la comuna elegida.
  if tg_op = 'INSERT'
     or (new.lat, new.lng, new.commune_id) is distinct from (old.lat, old.lng, old.commune_id) then
    if not coalesce(private.point_in_chile(new.lat, new.lng), false) then
      raise exception 'La ubicación debe estar en Chile' using errcode = '22023';
    end if;
    if not coalesce(private.point_in_commune(new.commune_id, new.lat, new.lng), false) then
      raise exception 'La ubicación marcada no está en la comuna elegida'
        using errcode = '22023';
    end if;
  end if;

  if new.active and (tg_op = 'INSERT' or not old.active) then
    perform pg_advisory_xact_lock(hashtextextended('addresses:' || new.owner_id::text, 0));
    if (select count(*) from public.addresses a
        where a.owner_id = new.owner_id and a.active and a.id <> new.id) >= 10 then
      raise exception 'Puedes tener hasta 10 direcciones activas' using errcode = '22023';
    end if;
  end if;

  return new;
end;
$$;
revoke execute on function private.guard_address() from public, anon, authenticated;

-- Comunas compatibles con un punto, de la más probable a la menos probable.
-- Como los límites están ampliados ~1 km, cerca de un borde varias comunas
-- "contienen" el punto. Se ordena por profundidad: primero la comuna donde el
-- punto queda más lejos del borde; después, las cercanas por distancia. La UI
-- la usa para proponer la comuna y limitar la elección. SECURITY INVOKER: solo
-- lee catálogos que authenticated ya puede leer.
create function public.communes_at_point(p_lat double precision, p_lng double precision)
returns table (commune_id integer, region_id smallint, name text, distance_m double precision)
language sql
stable
security invoker
set search_path = ''
as $$
  with p as (
    select extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326) pt
  ), hits as (
    select c.id, c.region_id, c.name,
           extensions.st_distance(b.area, p.pt::extensions.geography) as dist,
           case when extensions.st_covers(b.area::extensions.geometry, p.pt)
             then -extensions.st_distance(
                    extensions.st_boundary(b.area::extensions.geometry)::extensions.geography,
                    p.pt::extensions.geography)
             else extensions.st_distance(b.area, p.pt::extensions.geography)
           end as score
    from p
    join public.commune_boundaries b
      on extensions.st_dwithin(b.area, p.pt::extensions.geography, 2500)
    join public.communes c on c.id = b.commune_id
    union all
    select c.id, c.region_id, c.name, 0, 0
    from public.communes c
    where c.name = 'Antártica' and c.region_id = 12
      and p_lat <= -60 and p_lng between -90 and -53
  )
  select id, region_id, name, dist from hits
  order by score, name
  limit 10;
$$;
revoke execute on function public.communes_at_point(double precision, double precision)
  from public, anon;
grant execute on function public.communes_at_point(double precision, double precision)
  to authenticated;
